## Código completo (C++)

```cpp
#include <iostream>
#include <fstream>
#include <filesystem>
#include <vector>
#include <string>

#include <cryptopp/keccak.h>
#include <cryptopp/hex.h>
#include <cryptopp/files.h>

namespace fs = std::filesystem;

/* Estrutura que guarda o nome do arquivo e o seu hash Keccak‑512 */
struct FileEntry {
    std::string filename;   // nome completo do arquivo
    std::string hash;       // hash hexadecimal obtido
};

/* Calcula o hash Keccak‑512 de um caminho de arquivo */
std::string calculateKeccak512(const std::string& filePath) {
    CryptoPP::Keccak_512 hash;
    std::string digest;

    CryptoPP::FileSource(filePath.c_str(), true,
        new CryptoPP::HashFilter(hash,
            new CryptoPP::HexEncoder(
                new CryptoPP::StringSink(digest), true)));

    return digest;
}

int main() {
    /* -------------------------------------------------
       1️⃣ Abrir o arquivo que vai conter apenas os hashes
       ------------------------------------------------- */
    std::ofstream outputFile("rTalesHash.txt");          // <-- nome mudou para rTalesHash.txt
    if (!outputFile.is_open()) {
        std::cerr << "Erro ao abrir o arquivo de saída!" << std::endl;
        return 1;
    }

    /* -------------------------------------------------
       2️⃣ Percorre o diretório atual e coleta arquivos
           com extensões .exe, .dll ou .asi
       ------------------------------------------------- */
    std::vector<FileEntry> entries;                       // armazenará (nome, hash)
    const std::vector<std::string> extensions = { ".exe", ".dll", ".asi" };

    for (const auto& dirEntry : fs::directory_iterator(fs::current_path())) {
        if (dirEntry.is_regular_file()) {
            std::string ext = dirEntry.path().extension().string();
            if (std::find(extensions.begin(), extensions.end(), ext) != extensions.end()) {
                std::string filePath = dirEntry.path().string();
                std::string hash = calculateKeccak512(filePath);
                entries.push_back({ dirEntry.path().filename().string(),
                                   hash });
            }
        }
    }

    /* -------------------------------------------------
       3️⃣ Escreve os hashes no arquivo rTalesHash.txt
       ------------------------------------------------- */
    for (const auto& e : entries) {
        outputFile << "\"" << e.filename << "\" : " << e.hash << std::endl;
    }
    outputFile.close();

    /* -------------------------------------------------
       4️⃣ Mostra a lista dos arquivos encontrados
       ------------------------------------------------- */
    std::cout << "\nList of files found and their Keccak‑512 hashes:\n";
    for (const auto& e : entries) {
        std::cout << e.filename << '\t' << e.hash << '\n';
    }

    /* -------------------------------------------------
       5️⃣ Pergunta ao usuário quantas linhas ele quer colocar
           no arquivo separado “rTales.ini”
       ------------------------------------------------- */
    std::cout << "\nEnter the number of lines you want to write to 'rTales.ini'
                 (0 to quit):\n";
    int linesToWrite = 0;
    if (std::cin >> linesToWrite) {
        if (linesToWrite == 0) {
            std::cout << "Exiting without writing to rTales.ini.\n";
            return 0;
        }
        // Limita ao número de entradas disponíveis
        if (linesToWrite > static_cast<int>(entries.size())) {
            linesToWrite = entries.size();
        }

        std::ofstream outRatesIni("rTales.ini");
        if (!outRatesIni.is_open()) {
            std::cerr << "Erro ao abrir rTales.ini para escrita!\n";
            return 1;
        }
        for (int i = 0; i < linesToWrite; ++i) {
            outRatesIni << "\"" << entries[i].filename << "\" : " << entries[i].hash << std::endl;
        }
        outRatesIni.close();
    }

    std::cout << "Hashes calculados e salvos em rTalesHash.txt\n";
    std::cout << "Selected lines written to rTales.ini\n";
    return 0;
}
```

### Explicação rápida das mudanças

1. **Nome do arquivo de saída**  
   `std::ofstream outputFile("rTalesHash.txt");` – agora escreve os resultados em *rTalesHash.txt*.

2. **Estrutura `FileEntry`** – armazena simultaneamente o nome do arquivo e o hash já calculado.

3. **Lista de arquivos** – após preencher o vetor `entries`, o programa imprime cada linha como `filename<TAB>hash`. Isso serve como a tabela que você pode usar para selecionar.

4. **Seleção interativa** – pede ao usuário quantas linhas ele deseja copiar para o novo arquivo `rTales.ini`.  
